// 表單的資料在最外層，Webhook 的資料在 body 裡，兩種都能讀
const f = $input.first().json.body ?? $input.first().json;
const pick = prefix => {
  const k = Object.keys(f).find(k => k.startsWith(prefix));
  return k ? String(f[k] ?? '').trim() : '';
};
// 欄位名稱只比對開頭「分享」，表單全名和捷徑傳的短名都對得上
const 分享 = pick('分享');
// 語音聽寫可能多出空白或標點，先清掉再驗證是不是 6 位數
const 貨號輸入 = pick('貨號').replace(/[\s,，.。]/g, '');
const 顏色尺寸 = pick('顏色尺寸');

// 網址裡的內碼：有就直接用；沒有的話，後面用貨號去搜尋
const m = 分享.match(/(?:pid|productCode)=(u\d+)/i);
const 網址內碼 = m ? m[1] : null;

// 分享文字裡「獨立的六位數」（去重）。多貨號商品會抓到好幾個，不能亂猜第一個
const 文字貨號 = [...new Set(分享.match(/(?<!\w)\d{6}(?!\w)/g) || [])];

const 問題 = [];
let 貨號 = 貨號輸入;                         // 貨號欄有填 → 以貨號欄為準
if (貨號) {
  if (!/^\d{6}$/.test(貨號)) 問題.push({ 欄位: '貨號', 行: null, 訊息: '貨號要是 6 位數字' });
} else if (文字貨號.length === 1) {
  貨號 = 文字貨號[0];                         // 分享文字裡剛好一個 → 就是它
} else if (文字貨號.length > 1) {
  問題.push({ 欄位: '貨號', 行: null, 訊息: `分享文字裡有多個六位數（${文字貨號.join('、')}），請在貨號欄填你要追的那個` });
} else {
  問題.push({ 欄位: '貨號', 行: null, 訊息: '沒有貨號：請在貨號欄填 6 位數貨號' });
}

// 顏色尺寸：每行一組（這段跟舊版相同）
const 組合 = [];
const lines = 顏色尺寸.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
lines.forEach((ln, i) => {
  const parts = ln.split(/\s+/);
  if (parts.length < 2) {
    問題.push({ 欄位: '顏色尺寸', 行: i + 1, 訊息: '格式不對，要「色號或色名 空格 尺寸」' });
    return;
  }
  組合.push({ 行: i + 1, 原文: ln, 顏色: parts.slice(0, -1).join(' '), 尺寸: parts[parts.length - 1] });
});
if (lines.length === 0) 問題.push({ 欄位: '顏色尺寸', 行: null, 訊息: '沒有填' });

return [{ json: {
  productCode: 網址內碼, 貨號, 組合,           // productCode 可能是 null，等「取內碼」補
  原_分享: 分享, 原_貨號: 貨號輸入, 原_顏色尺寸: 顏色尺寸,
  問題, 階段: '解析',
  錯誤: 問題.length ? 問題.map(x => x.訊息).join('\n') : null,
  候選: ''
} }];

function findAll(obj, key, out = []) {
  if (obj === null || typeof obj !== 'object') return out;
  if (key in obj) out.push(obj[key]);
  for (const k of Object.keys(obj)) findAll(obj[k], key, out);
  return out;
}
const p = $('取內碼').last().json;
const base = { 原_分享: p.原_分享, 原_貨號: p.原_貨號, 原_顏色尺寸: p.原_顏色尺寸 };
const d = $input.first().json;
const rows = findAll(d, 'rows')
  .find(r => Array.isArray(r) && r.length > 0 && r[0] && r[0].productId) || [];
if (rows.length === 0) {
  const 問題 = [{ 欄位: '分享', 行: null, 訊息: `抓不到商品資料（內碼 ${p.productCode}）` }];
  return [{ json: { ...base, 問題, 階段: '比對', 錯誤: 問題.map(x => x.訊息).join('\n'), 候選: '' } }];
}

const norm = s => String(s ?? '').trim().toLowerCase().replace(/\s+/g, '');
const colorKey = s => norm(s).replace(/^col/, '');
const noZero = x => String(x).replace(/^0+(?=\d)/, '');
// 尺寸比對：「64」「64cm」「26inch」都只比數字部分；S/M/L/XL 照字串比
const sizeKey = x => {
  const n = norm(x);
  const m = n.match(/^(\d+(?:\.\d+)?)(cm|inch|in|吋|")?$/);
  return m ? m[1] : n;
};
// 從 styleText 取貨號：「480054 / 09 BLACK」→ 480054
const 款Of = r => (String(r.styleText ?? '').match(/\d{6}/) || [''])[0];

const ok = [];
const bad = [];
for (const g of p.組合) {
  // 顏色欄裡的六位數是「貨號」（再版用），拆出來；剩下的才是色號或色名
  const toks = String(g.顏色).trim().split(/\s+/);
  const 指定款 = toks.find(t => /^\d{6}$/.test(t)) || '';
  const c = norm(toks.filter(t => t !== 指定款).join(' '));
  const isDigits = /^\d+$/.test(c);

  let hits = rows.filter(r => {
    if (sizeKey(r.size) !== sizeKey(g.尺寸)) return false;
    const code = colorKey(r.colorNo);
    if (isDigits) return noZero(code) === noZero(c);   // 只打數字：只比色號
    return code === colorKey(c) || norm(r.styleText).includes(c);
  });
  if (指定款) {
    hits = hits.filter(r => 款Of(r) === 指定款);         // 你有寫貨號：照你寫的
  } else if (hits.length > 1) {                          // 沒寫、但同色號有多個貨號：用表單的貨號挑
    const narrowed = hits.filter(r => 款Of(r) === String(p.貨號));
    if (narrowed.length) hits = narrowed;
  }

  if (hits.length === 1) {
    const h = hits[0];
    ok.push({ ...base, 行: g.行, 貨號: p.貨號, 內碼: p.productCode, 色號: h.colorNo, 尺寸: h.size,
      商品名: h.name, 色名: h.styleText, 現價: h.price });
  } else {
    bad.push({ 欄位: '顏色尺寸', 行: g.行,
      訊息: hits.length === 0 ? '找不到符合的顏色與尺寸'
        : '符合不只一個，請在色號後面加貨號（例：COL09 483537 M）' });
  }
}
if (bad.length) {
  const by = {};
  for (const r of rows) {
    const 款 = 款Of(r);
    const 色名 = String(r.styleText ?? '').split('/').slice(1).join('/').trim() || r.styleText;
    (by[`${r.colorNo}${款 ? ' ' + 款 : ''}（${色名}）`] ??= []).push(r.size);
  }
  const 候選 = Object.entries(by).map(([k, v]) => `${k}：${[...new Set(v)].join('、')}`).join('\n');
  return [{ json: { ...base, 問題: bad, 階段: '比對', 錯誤: bad.map(x => `第 ${x.行} 行：${x.訊息}`).join('\n'), 候選 } }];
}
return ok.map(o => ({ json: o }));

const incoming = $('比對').all().map(i => i.json);
const key = (a, b, c) => [a, b, c].map(v => String(v ?? '').trim()).join('|');
const have = new Map($input.all().map(i => i.json)
  .map(r => [key(r['內碼'], r['色號'], r['尺寸']), r]));
const fresh = [], skipped = [], dups = [], seen = new Set();
for (const h of incoming) {
  const k = key(h.內碼, h.色號, h.尺寸);
  if (have.has(k)) {
    const r = have.get(k);
    const 說明 = `${h.色名} ${h.尺寸}（清單第 ${r.row_number} 列，啟用：${r['啟用']}）`;
    skipped.push(說明);
    dups.push({ 欄位: '顏色尺寸', 行: h.行, 訊息: `已在追蹤清單：${說明}` });
  } else if (seen.has(k)) {
    skipped.push(`${h.色名} ${h.尺寸}（這次重複輸入）`);
    dups.push({ 欄位: '顏色尺寸', 行: h.行, 訊息: '這次重複輸入' });
  } else { seen.add(k); fresh.push(h); }
}
const 略過 = skipped.join('；');
if (fresh.length === 0) {
  const h0 = incoming[0];
  return [{ json: { 原_分享: h0.原_分享, 原_貨號: h0.原_貨號, 原_顏色尺寸: h0.原_顏色尺寸,
    問題: dups, 階段: '查重複', 錯誤: `這次的組合全都已經在追蹤了：${略過}`, 候選: '' } }];
}
return fresh.map(h => ({ json: { ...h, 庫存門檻: 20, 啟用: 'Y', 略過, 略過數: skipped.length } }));

const items = $('查重複').all().map(i => i.json);
const h0 = items[0];
const lines = items.map(h => `　🆗 ${h.色名} ${h.尺寸}（NT$ ${h.現價}）`).join('
');
let 訊息 = `🤑 已新增 ${items.length} 筆追蹤
${h0.商品名}
${lines}`;
if (h0.略過數) 訊息 += `

略過 ${h0.略過數} 筆（已在追蹤）：${h0.略過}`;
訊息 += '

「🆕 開始追蹤」通知會發到追價頻道。';
return [{ json: { 訊息 } }];

const e = $input.first().json;
const 問題 = e.問題 ?? [];
const 整欄問題 = f => 問題.filter(x => x.欄位 === f && x.行 == null);
const 該行問題 = n => 問題.filter(x => x.欄位 === '顏色尺寸' && x.行 === n);
const cut = (s, n) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
};
const lines = String(e.原_顏色尺寸 ?? '').split(/\r?\n/).map(s => s.trim()).filter(Boolean);
// 解析階段就卡在內碼或貨號 → 顏色尺寸還沒比對過，用 ➖ 表示「未檢查」
// 原本只有「解析」階段才算未檢查；現在「查內碼」失敗時，顏色尺寸也還沒比對過
const 未檢查 = (e.階段 === '解析' || e.階段 === '查內碼') && 問題.some(x => x.欄位 === '分享' || x.欄位 === '貨號');

const out = [' 💔 新增追蹤失敗，這次沒有寫入任何資料', '──────────────'];

const a = 整欄問題('分享');
out.push(`📎 分享內容或網址　${a.length ? '🆘' : '👌'}`);
out.push(`　${cut(e.原_分享, 60) || '（空白）'}`);
a.forEach(x => out.push(`　→ ${x.訊息}`));

const b = 整欄問題('貨號');
out.push(`🔢 貨號　${b.length ? '🆘' : '👌'}　${cut(e.原_貨號, 20) || '（沒填）'}`);
b.forEach(x => out.push(`　→ ${x.訊息}`));

const c = 整欄問題('顏色尺寸');
const 有行問題 = lines.some((_, i) => 該行問題(i + 1).length);
out.push(`🎨 顏色尺寸　${c.length || 有行問題 ? '🆘' : (未檢查 ? '🔙' : '👌')}`);
c.forEach(x => out.push(`　→ ${x.訊息}`));
lines.forEach((ln, i) => {
  const ps = 該行問題(i + 1);
  if (ps.length) out.push(`　🆘 ${ln}　← ${ps.map(x => x.訊息).join('；')}`);
  else out.push(`　${未檢查 ? '🔙' : '👌'} ${ln}`);
});

if (e.候選) {
  const 候選 = e.候選.length > 700 ? e.候選.slice(0, 700) + '\n…（太長，已截斷）' : e.候選;
  out.push('──────────────', '可選的顏色尺寸：', 候選);
}
out.push('──────────────', '修改後請重新送出表單。要複製的內容：');
// 網址：從分享內容裡抓第一段 https://…
const url = (String(e.原_分享 ?? '').match(/https?:\/\/\S+/) || [''])[0];
// 貨號：跟 `解析` 同樣的規則（分享文字裡獨立的六位數；沒有就用「貨號」欄）
const m6 = String(e.原_分享 ?? '').match(/(?<!\w)(\d{6})(?!\w)/);
// 貨號欄有填就用它；沒填才從分享文字抓（跟「解析」同一個順序）
const 貨號 = String(e.原_貨號 ?? '').trim() || (m6 ? m6[1] : '');
// 有內容才放區塊
const block = (標題, 內容) => { if (內容) out.push(標題, '```', 內容, '```'); };
block('網址', url.slice(0, 400));
block('貨號', 貨號);
block('顏色尺寸', lines.join('\n'));

return [{ json: { 訊息: out.join('\n') } }];

const p = $('解析').last().json;               // 解析的資料（貨號、顏色尺寸等）
const res = $input.first().json;               // 搜尋結果
const 貨號 = String(p.貨號);

// 搜尋回傳裡，找出所有有 productName 的物件（不管包在哪一層）
const collect = (o, out = []) => {
  if (o === null || typeof o !== 'object') return out;
  if (typeof o.productName === 'string') out.push(o);
  for (const k of Object.keys(o)) collect(o[k], out);
  return out;
};
// 內碼：優先讀 productCode 欄位；沒有就從主圖路徑撈（/hmall/test/u0000000054254/...）
const 內碼Of = o => (`${o.productCode ?? ''} ${o.mainPic ?? ''}`.match(/u\d{6,}/) || [''])[0];

// 搜尋是模糊比對，所以要再確認「商品名稱裡真的有這個獨立的貨號」
const re = new RegExp(`(?<!\\d)${貨號}(?!\\d)`);
const codes = [...new Set(collect(res).filter(o => re.test(o.productName)).map(內碼Of).filter(Boolean))];

const fail = 訊息 => [{ json: { ...p, 問題: [{ 欄位: '貨號', 行: null, 訊息 }], 階段: '查內碼', 錯誤: 訊息 } }];

if (p.productCode) return [{ json: { ...p, 錯誤: null } }];   // 網址有內碼 → 直接用，搜尋失敗也不擋
if (res.error) return fail('貨號搜尋的請求失敗了，稍後再試或改貼網址');
if (codes.length === 0) return fail(`搜尋找不到貨號 ${貨號}（打錯，或商品已下架）`);
if (codes.length > 1) return fail(`貨號 ${貨號} 對到多個商品，請改貼網址`);
return [{ json: { ...p, productCode: codes[0], 錯誤: null } }];

// 彙整成一則通知；列太多時只列前 15 列，避免超過 Discord 字數上限
const items = $('找列').all().map(i => i.json);
const 動作 = items[0].動作;
const 列出 = items.slice(0, 15).map(r =>
  `・${r.貨號} ${r.色號} ${r.尺寸}${r.商品名稱 ? `｜${String(r.商品名稱).slice(0, 30)}` : ''}`);
if (items.length > 15) 列出.push(`…另外 ${items.length - 15} 列`);
const 附註 = items[0].附註 ? `\n${items[0].附註}` : '';
const 訊息 = 動作 === '停追'
  ? `⏸️ 已停追 ${items.length} 列\n${列出.join('\n')}${附註}`
  : `已重新啟用。（${items.length} 列）\n${列出.join('\n')}${附註}`;
return [{ json: { 訊息 } }];

// 停追／啟用：依貨號（＋顏色尺寸）在追蹤清單找出要改的列
const b = $('Webhook').first().json.body ?? {};
const 動作 = String(b['動作'] ?? '').trim();               // 「停追」或「啟用」
const 貨號 = String(b['貨號'] ?? '').trim();
const 輸入原 = String(b['顏色尺寸'] ?? '').trim();            // 留空 = 該貨號全部列
// 語音很難「留空」，所以說「整件」或「全部」也視為整個貨號
const 輸入 = ['整件', '全部'].includes(輸入原) ? '' : 輸入原;
const rows = $input.all().map(i => i.json);

// 出錯或沒東西可改：回一筆帶「錯誤」的資料，後面直接送去通知
const stop = 訊息 => [{ json: { 錯誤: 訊息, 訊息 } }];

if (!/^\d{6}$/.test(貨號)) return stop(`❌ ${動作}失敗：貨號要是 6 位數字`);
const 同貨號 = rows.filter(r => String(r['貨號'] ?? '').trim() === 貨號);
if (同貨號.length === 0) return stop(`❌ ${動作}失敗：追蹤清單裡沒有貨號 ${貨號}`);

// 目標列：沒填顏色尺寸 → 整個貨號；有填 → 一行一組「色號 尺寸」
let 目標 = [];
const 找不到 = [];
if (!輸入) {
  目標 = 同貨號;
} else {
  for (const ln of 輸入.split(/\r?\n/).map(s => s.trim()).filter(Boolean)) {
    const parts = ln.split(/\s+/);
    if (parts.length < 2) { 找不到.push(`${ln}（格式要「色號 空格 尺寸」）`); continue; }
    const 尺寸 = parts[parts.length - 1].toLowerCase();
    const c = parts.slice(0, -1).join(' ').toUpperCase();
    const 色號 = /^\d+$/.test(c) ? `COL${c}` : c;          // 78 → COL78；直接打 COL78 也行
    const hit = 同貨號.filter(r =>
      String(r['色號'] ?? '').trim().toUpperCase() === 色號 &&
      String(r['尺寸'] ?? '').trim().toLowerCase() === 尺寸);
    if (hit.length === 0) 找不到.push(ln); else 目標.push(...hit);
  }
}
目標 = [...new Set(目標)];   // 去掉重複的列

// 只處理「需要改」的列：停追 → 目前不是 N；啟用 → 目前不是 Y
const 現在 = r => String(r['啟用'] ?? '').trim().toUpperCase();
const 要改 = 目標.filter(r => 動作 === '停追' ? 現在(r) !== 'N' : 現在(r) !== 'Y');

const 已是 = 目標.length - 要改.length;
const 附註 = [
  已是 > 0 ? `（${已是} 列本來就是${動作 === '停追' ? '停追' : '啟用'}狀態）` : '',
  找不到.length ? `找不到：${找不到.join('、')}` : ''
].filter(Boolean).join('\n');

if (要改.length === 0) return stop(`ℹ️ 沒有需要${動作}的列\n${附註}`.trim());

return 要改.map(r => ({ json: {
  row_number: r.row_number, 動作, 貨號: r['貨號'], 色號: r['色號'], 尺寸: r['尺寸'],
  商品名稱: r['商品名稱'] ?? '',
  新_啟用: 動作 === '停追' ? 'N' : 'Y',
  // 啟用時清空「上次現價」→ 下一輪視為新追蹤、重發「開始追蹤」；停追時原值寫回，等於不動
  新_上次現價: 動作 === '啟用' ? '' : (r['上次現價'] ?? ''),
  附註
} }));
